from pathlib import Path
from html import escape
import re
P=Path(__file__).parent/'dist'
base=(P/'operations.html').read_text()
header=base[base.index('<header class="site-header">'):base.index('</header>')+9]
footer=base[base.index('<footer>'):base.index('</footer>')+9]

def head(title,description):
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#0b2740"><meta name="description" content="{escape(description,quote=True)}"><title>{escape(title)} | ArcHorizon</title><link rel="icon" type="image/png" href="archorizon-app-icon.png"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Exo+2:wght@600;700;800&family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet"><link rel="stylesheet" href="styles.css"><script src="theme.js" defer></script></head><body>'''
def shot(title,ratio='wide',kind='Desktop application'):
 return f'''<figure class="showcase-shot {ratio}"><div class="showcase-placeholder"><span class="shot-kicker">SCREENSHOT SPACE · {escape(kind.upper())}</span><span class="shot-icon" aria-hidden="true">▣</span><strong>{escape(title)}</strong><span class="shot-note">Add your ArcHorizon capture here</span></div><figcaption>Suggested capture: {escape(title.lower())}.</figcaption></figure>'''
def page(filename,title,description,body):
 h=header.replace('href="operations.html" aria-current="page"','href="operations.html"')
 f=P/filename;f.write_text(head(title,description)+'<div id="top">'+h+body+footer+'</div></body></html>')

intro=lambda crumb,kicker,title,lead:f'''<section class="tool-hero"><div class="wrap"><div class="breadcrumb"><a href="index.html">Overview</a> / <a href="operations.html">Operations</a> / {crumb}</div><span class="eyebrow">{kicker}</span><h1>{title}</h1><p>{lead}</p></div></section>'''
related='''<section class="section dark"><div class="wrap"><span class="eyebrow">The operations workspace</span><h2>Work from the same record.</h2><div class="related"><a href="operations.html">Operations overview →</a><a href="tasks.html">Tasks &amp; assignments →</a><a href="teams.html">Teams &amp; crews →</a><a href="status-boards.html">Status boards →</a></div></div></section>'''

# Tasks: lead with the actual assignment record and show how map, team, and logs join it.
tasks='<main class="tool-detail tasks-detail">'+intro('Tasks &amp; Assignments','Operational tasking','Make the assignment clear before the team moves.','A task keeps the objective, location, assigned resource, supervisor, and operational constraints together. As the work proceeds, status and field reporting remain connected to that same assignment.')+f'''<section class="section"><div class="wrap task-feature-grid"><div><span class="eyebrow">The task record</span><h2>One place for the work to be done.</h2><p class="lead">A useful assignment answers who, what, where, when, and what result is expected. It also gives the team enough context to act without searching through unrelated incident records.</p><dl class="task-anatomy"><div><dt>Objective</dt><dd>Purpose and expected result</dd></div><div><dt>Location</dt><dd>Area, map geometry, and access</dd></div><div><dt>Assignment</dt><dd>Team and supervisor</dd></div><div><dt>Constraints</dt><dd>Hazards, timing, and communications</dd></div><div><dt>Record</dt><dd>Status, narrative, and outcome</dd></div></dl></div>{shot('Task detail with assignment, map reference, and team')}</div></section><section class="section alt"><div class="wrap"><div class="section-head"><span class="eyebrow">Task progress</span><h2>Follow the work, not just the dispatch.</h2><p class="lead">Task status describes progress on the assignment. Team status describes the resource carrying it out; the two move together but answer different questions.</p></div><div class="task-track"><div><b>Planned</b><span>Define the work and the area.</span></div><div><b>Assigned</b><span>Attach the team and supervisor.</span></div><div><b>In progress</b><span>Follow field updates and changes.</span></div><div><b>Complete</b><span>Record result and any follow-up.</span></div></div></div></section><section class="section"><div class="wrap task-result-grid">{shot('Assignment map showing segment, access, and hazards')}<div><span class="eyebrow">Geographic context</span><h2>The map travels with the assignment.</h2><p class="lead">A task can carry a planning segment, search area, route, hazard, or other operational feature. That geography is available to the field team and remains linked to the resulting report.</p><a class="text-link" href="mapping.html">Explore mapping &amp; GIS →</a></div></div></section><section class="section alt"><div class="wrap task-result-grid"><div><span class="eyebrow">What comes back</span><h2>Close the loop with the field result.</h2><p class="lead">Status and narrative updates, observations, clues, and hazards can change what the next team needs to do. Keep the outcome with the task and feed actionable findings into planning.</p><div class="tool-links"><a href="field.html">Field reporting →</a><a href="planning.html">Planning →</a><a href="documentation.html">Incident logs →</a></div></div>{shot('Task history and field narrative log')}</div></section>'''+related+'</main>'
page('tasks.html','Tasks & Assignments','Create, assign, map, track, and document operational tasks in ArcHorizon.',tasks)

teams='<main class="tool-detail teams-detail">'+intro('Teams &amp; Crews','Resource accountability','Know the people and equipment behind the callsign.','Team records bring together staffing, capabilities, vehicles, aircraft, equipment, current status, and activity. Operations can see whether a resource is ready for the next assignment and what it is doing now.')+f'''<section class="section"><div class="wrap team-hero-grid">{shot('Team detail with personnel, equipment, vehicles, aircraft, and logs')}<div><span class="eyebrow">Team detail</span><h2>One resource, several connected views.</h2><p class="lead">The team detail window adapts to the resource type. A ground team, aircrew, UAS crew, K9 team, or utility team sees the relevant personnel and equipment context.</p><div class="team-tabs" aria-label="Team record areas"><span>Personnel</span><span>Aircrew</span><span>Equipment</span><span>Vehicles</span><span>Aircraft</span><span>Logs</span></div></div></div></section><section class="section alt"><div class="wrap"><div class="section-head"><span class="eyebrow">Resource types</span><h2>Describe capability without hiding accountability.</h2><p class="lead">Team type shapes the detail view, while assignment and status show what that resource is doing.</p></div><div class="team-type-grid"><article><h3>Ground &amp; location</h3><p>Ground, lost-person search, direction-finding, K9, and utility resources.</p><span>GT · LSAR · UDF · DF · K9 · UTIL</span></article><article><h3>Air &amp; UAS</h3><p>Aircraft and remotely piloted teams, including mixed ground/UAS capability.</p><span>AIR · HELO · UAS · GT/UAS · UDF/UAS</span></article><article><h3>Planned event</h3><p>Staff and vehicle context for teams assigned to event operations.</p><span>PERSONNEL · VEHICLES · TASKS</span></article></div></div></section><section class="section"><div class="wrap team-two-col"><div><span class="eyebrow">Readiness and status</span><h2>Availability is an operational fact.</h2><p class="lead">A team can be available, assigned, briefed, en route, on scene, returning, resting, or out of service. The current status belongs beside its assignment and its staffing.</p><ul class="ops-checks"><li>Review composition and qualifications before tasking.</li><li>See assigned vehicles, aircraft, and equipment.</li><li>Record movement, rest, and changes to availability.</li></ul></div>{shot('Team roster and status controls','portrait')}</div></section><section class="section alt"><div class="wrap team-two-col">{shot('Team task, status, unit, and ICS-214 logs')}<div><span class="eyebrow">Activity history</span><h2>Every status change has context.</h2><p class="lead">Task, status, unit, and activity logs keep the team’s work traceable. Follow the record from briefing through return and use it when writing the incident narrative.</p><div class="tool-links"><a href="tasks.html">Tasks &amp; assignments →</a><a href="documentation.html">Documentation →</a></div></div></div></section>'''+related+'</main>'
page('teams.html','Teams & Crews','Track team composition, capability, equipment, aircraft, status, and logs in ArcHorizon.',teams)

boards='<main class="tool-detail boards-detail">'+intro('Status Boards','Live operational picture','Two boards. Two different decisions.','The team board answers which resources are ready, moving, working, or unavailable. The task board answers which assignments are planned, assigned, in progress, or complete. Together they show capacity and workload.')+f'''<section class="section"><div class="wrap"><div class="board-comparison"><article><span class="eyebrow">Resource state</span><h2>Team board</h2><p>Track current status across ground, air, UAS, K9, direction-finding, and support teams. Supervisors can see who can take work and who needs attention.</p>{shot('Team status board with resource cards','wide')}</article><article><span class="eyebrow">Work state</span><h2>Task board</h2><p>Follow assignments from plan through completion. Each task stays connected to the assigned team, map area, and field result.</p>{shot('Task status board with assignment cards','wide')}</article></div></div></section><section class="section alt"><div class="wrap board-workflow"><div><span class="eyebrow">A useful difference</span><h2>One team can change status while its task stays active.</h2><p class="lead">The boards keep resource movement separate from assignment progress. A team may be returning or taking a break while a task remains open for another team or follow-up.</p></div><div class="board-questions"><div><strong>Can this resource take another assignment?</strong><span>Check the team board and its detail record.</span></div><div><strong>Which work remains unfinished?</strong><span>Check the task board and task history.</span></div><div><strong>What changed since the last briefing?</strong><span>Review status transitions and field entries.</span></div></div></div></section><section class="section"><div class="wrap board-presentation">{shot('Commander projection board with teams and tasks stacked')}<div><span class="eyebrow">Command display</span><h2>Keep the board readable in the command post.</h2><p class="lead">The projection view stacks teams and tasks with alerts, weather, incident information, and a clock. Staff control board order while status changes update the underlying records.</p><a class="text-link" href="situational-awareness.html">See the common operating picture →</a></div></div></section>'''+related+'</main>'
page('status-boards.html','Status Boards','Compare team availability and assignment progress on ArcHorizon operations boards.',boards)

# Put concrete operations tools high on the overview, before the assignment lifecycle.
f=P/'operations.html';s=f.read_text()
start=s.index('<section class="section"><div class="wrap"><div class="section-head"><span class="eyebrow">Assignment lifecycle')
section='''<section class="section operations-tools"><div class="wrap"><div class="section-head"><span class="eyebrow">Operations tools</span><h2>The records behind the board.</h2><p class="lead">Open the task, the team, or the status board to work at the level the situation requires.</p></div><div class="ops-tools-grid"><a href="tasks.html"><span>01 / TASKS</span><h3>Tasks &amp; assignments</h3><p>Define the work, assign a team, attach geography, and follow the result.</p><strong>Explore tasks →</strong></a><a href="teams.html"><span>02 / RESOURCES</span><h3>Teams &amp; crews</h3><p>See staffing, equipment, vehicles, aircraft, capabilities, and activity in one team record.</p><strong>Explore teams →</strong></a><a href="status-boards.html"><span>03 / STATUS</span><h3>Status boards</h3><p>Separate team availability from task progress while keeping them connected.</p><strong>Explore boards →</strong></a></div></div></section>'''
s=s[:start]+section+s[start:];f.write_text(s)
# Add a first-class category to the full Features directory.
f=P/'features.html';s=f.read_text();target='<section class="feature-group"><h2>Search &amp; geography</h2>'
# The existing heading uses an unescaped ampersand in source; support both forms.
if target not in s:target='<section class="feature-group"><h2>Search & geography</h2>'
assert target in s
addition='''<section class="feature-group"><h2>Operations tools</h2><ul><li><strong><a href="tasks.html">Tasks &amp; assignments</a></strong><span>Define, assign, map, track, and close operational work.</span></li><li><strong><a href="teams.html">Teams &amp; crews</a></strong><span>Staffing, capability, equipment, status, and activity in one record.</span></li><li><strong><a href="status-boards.html">Status boards</a></strong><span>Team availability and task progress in separate, connected views.</span></li></ul></section>'''
s=s.replace(target,addition+target,1);f.write_text(s)
# Expose the tools from every footer, without adding three links to an already busy top navigation.
for f in P.glob('*.html'):
 s=f.read_text();needle='<li><a href="features.html">All features</a></li>'
 if needle in s and '<li><a href="tasks.html">Tasks &amp; assignments</a></li>' not in s:
  s=s.replace(needle,needle+'<li><a href="tasks.html">Tasks &amp; assignments</a></li><li><a href="teams.html">Teams &amp; crews</a></li><li><a href="status-boards.html">Status boards</a></li>',1)
  f.write_text(s)
css='''
/* Operations tools: task, team, and board detail pages. */
.operations-tools{background:#edf3f6}.ops-tools-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.ops-tools-grid a{display:block;background:#fff;border:1px solid var(--line);border-top:4px solid var(--orange);padding:30px;text-decoration:none}.ops-tools-grid a:hover{border-color:var(--orange);transform:translateY(-2px)}.ops-tools-grid span{color:#a4550a;font-size:.78rem;letter-spacing:.13em;font-weight:800}.ops-tools-grid h3{font-size:1.55rem;margin:24px 0 12px}.ops-tools-grid p{color:var(--muted)}.ops-tools-grid strong{color:#a45100}.tool-hero{background:linear-gradient(110deg,#071c30,#123a57 75%,#315876);color:#fff;padding:64px 0 72px;border-bottom:4px solid var(--orange)}.tool-hero .breadcrumb{color:#b8d0dc}.tool-hero .eyebrow{color:#ffad61}.tool-hero h1{max-width:920px}.tool-hero p{font-size:1.18rem;color:#d9e6ec;max-width:820px}.tool-detail .section-head{max-width:780px}.task-feature-grid,.task-result-grid,.team-hero-grid,.team-two-col,.board-workflow,.board-presentation{display:grid;grid-template-columns:1fr 1fr;gap:65px;align-items:center}.task-anatomy{margin:30px 0 0;border-top:3px solid var(--orange)}.task-anatomy>div{display:grid;grid-template-columns:130px 1fr;gap:16px;border-bottom:1px solid var(--line);padding:13px 0}.task-anatomy dt{font-weight:800}.task-anatomy dd{margin:0;color:var(--muted)}.task-track{display:grid;grid-template-columns:repeat(4,1fr);border:1px solid var(--line)}.task-track>div{padding:24px;border-right:1px solid var(--line)}.task-track>div:last-child{border:0}.task-track b{display:block;font:700 1.25rem 'Exo 2',sans-serif;margin-bottom:8px}.task-track span{color:var(--muted)}.tool-links{display:flex;flex-wrap:wrap;gap:12px 20px;margin-top:20px}.tool-links a{color:#a45100;font-weight:750;text-underline-offset:4px}.team-tabs{display:flex;flex-wrap:wrap;gap:8px;margin-top:28px}.team-tabs span{padding:7px 11px;border:1px solid var(--line);font-weight:650;background:#edf3f6}.team-type-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.team-type-grid article{background:#fff;border:1px solid var(--line);padding:25px}.team-type-grid article span{font-size:.8rem;color:#9f5109;font-weight:800;letter-spacing:.05em}.team-type-grid p{color:var(--muted)}.board-comparison{display:grid;grid-template-columns:1fr 1fr;gap:26px}.board-comparison article{border-top:4px solid var(--steel);padding-top:23px}.board-comparison p{color:var(--muted);max-width:540px}.board-comparison .showcase-shot{margin-top:26px}.board-questions{border-top:3px solid var(--orange)}.board-questions>div{padding:18px 0;border-bottom:1px solid var(--line)}.board-questions strong,.board-questions span{display:block}.board-questions span{color:var(--muted)}body[data-theme="dark"] .operations-tools{background:#102f47}body[data-theme="dark"] .ops-tools-grid a,body[data-theme="dark"] .team-type-grid article{background:#173a52;border-color:#3e6076}body[data-theme="dark"] .ops-tools-grid span,body[data-theme="dark"] .team-type-grid article span{color:#ffad61}body[data-theme="dark"] .ops-tools-grid strong,body[data-theme="dark"] .tool-links a{color:#ffb76f}body[data-theme="dark"] .team-tabs span{background:#173a52}@media(max-width:950px){.task-feature-grid,.task-result-grid,.team-hero-grid,.team-two-col,.board-workflow,.board-presentation{grid-template-columns:1fr;gap:32px}.ops-tools-grid,.team-type-grid{grid-template-columns:1fr 1fr}}@media(max-width:700px){.ops-tools-grid,.team-type-grid,.board-comparison{grid-template-columns:1fr}.task-track{grid-template-columns:1fr 1fr}.task-track>div:nth-child(2){border-right:0}.task-track>div:nth-child(-n+2){border-bottom:1px solid var(--line)}.task-anatomy>div{grid-template-columns:1fr;gap:3px}.tool-hero{padding:50px 0 58px}}
'''
with (P/'styles.css').open('a') as out:out.write(css)
# Prevent the old generator from overwriting new static pages' directory/footer if run again.
gen=Path(__file__).parent/'generate_sections.py';t=gen.read_text();t=t.replace("(P/'features.html').write_text(feature_page)","# features.html is maintained with the Operations tools directory in build_operations_tools.py.\n# (P/'features.html').write_text(feature_page)")
gen.write_text(t)
